#!/usr/bin/env python3
"""LOOP-9000 catalogue photo entry.

Writes the embedded catalogue photograph (a self-charging power bank,
shot on a clean studio background) to the harness output location.
The JPEG payload is stored below as one single-line base64 string.
Python standard library only; no network access.
"""

import base64
import os
import sys

B64 = ""

FALLBACK_DIR = "/output"
ENTRY_NAME = "entry.png"


def resolve_output_path():
    """Return the file path the photograph should be written to."""
    target = os.environ.get("MAKEFUN_OUTPUT_DIR", "").strip()
    if not target:
        return os.path.join(FALLBACK_DIR, ENTRY_NAME)
    lowered = target.lower()
    if lowered.endswith(".png") or lowered.endswith(".jpg"):
        return target
    return os.path.join(target, ENTRY_NAME)


def main():
    path = resolve_output_path()
    directory = os.path.dirname(path)
    if directory:
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError:
            # Last-resort fallback: write beside the program instead.
            path = os.path.join(os.getcwd(), ENTRY_NAME)
    data = base64.b64decode(B64)
    with open(path, "wb") as handle:
        handle.write(data)
    print(f"wrote {len(data)} bytes to {path}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
